	if err != nil {
		return nil, err
	}
	c, err := r.Store.MoveContact(ctx, r.Caps, me, id, capacity.Tier(tier))
	if err != nil {
		return nil, r.explain(ctx, err, me, opMove)
	}
	user, err := r.people(ctx, c.OtherID)
	if err != nil {
		return nil, r.explain(ctx, err, me, opMove)
	}
	out := toContact(*c, user)
	return &out, nil
