              ? 'Full. Accepting anyone new needs a seat freed first, whatever the tier.'
              : `${data.capacity.budgetCap - data.capacity.budgetUsed} seat${
                  data.capacity.budgetCap - data.capacity.budgetUsed === 1 ? '' : 's'
                } left across all tiers.`}
          </Text>
        </View>
      )}

