        TIERS.map((t) => {
          const cap = capOf(t);
          const rows = byTier(t);
          return (
            <Section
              key={t}
              title={TIER_LABEL[t]}
              right={cap ? <Counter used={cap.used} cap={cap.cap} color={TIER_COLOR[t]} /> : null}
